def Test(n, a, k):
	dp = [0] * n
	dp[0] = a[0]
	for i in range(1, n):
		dp[i] = dp[i - 1] + a[i]
	s = [0] * k
	r = 0
	for i in range(k):
		s[i] = dp[n - k + i] - r & 1
		r = dp[i]
	return s.count(1)
for _ in range(int(input())):
	(n, k) = map(int, input().split())
	a = list(map(int, [*input()]))
	print(Test(n, a, k))
